#!/bin/sh
# Builds the signed Documents App with its page as a self-contained client view. Run through
# cargo-slot.sh from the repository root; every generated byte stays in the output directory, which
# must be outside the checkout.
# usage: build-package.sh <absolute output directory>
set -eu
: "${CARGO_TARGET_DIR:?use cargo-slot.sh}"
output=${1:?usage: build-package.sh <absolute output directory>}
case "$output" in /*) ;; *) echo 'The output directory must be absolute' >&2; exit 2;; esac
root=$(pwd)
case "$output/" in "$root/"*) echo 'The output directory must be outside the checkout' >&2; exit 2;; esac
app=examples/apps/documents
mkdir -p "$output"
cargo build --locked --manifest-path "$app/backend/Cargo.toml" --target wasm32-wasip2 --release
cargo run --locked -p chariox-app-sdk-tools --bin chariox-app-component -- \
  "$CARGO_TARGET_DIR/wasm32-wasip2/release/chariox_documents.wasm" "$output/documents.core.wasm"
node "$app/scripts/build-client-view.mjs" "$output/view"
cargo run --locked -p chariox-app-wasm-worker --example client-view-package -- "$output/documents.core.wasm" "$output/view/index.html" "$app" "$output"
